#include <iostream>
#include <vector>
#include <string>
#include <unordered_set>
using namespace std;

int main() {
    string jewels;
    cin >> jewels;
    string stones;
    cin >> stones;

    unordered_set<char> jewelSet(jewels.begin(), jewels.end());
    int count = 0;
    for (char stone : stones) {
        if (jewelSet.count(stone)) count++;
    }
    cout << count << "\n";

    return 0;
}

